  const cache = {};
  function roleArt(id, mode = 'scene') {
    const key = id + ':' + mode;
    if (cache[key]) return cache[key];
    const vb = mode === 'portrait' ? '46 22 108 108' : '0 0 200 200';
    let inner;
    if (PREMIUM[id]) { const [bg, ch, fx] = PREMIUM[id](id); inner = `<g class="ly ly-bg">${bg}</g><g class="ly ly-ch">${ch}</g><g class="ly ly-fx">${fx}</g>`; }
    else { const fn = SCENES[id] || SCENES.sheriff; inner = fn(id); }
    const svg = `<svg class="art-svg ${mode} ${PREMIUM[id] ? 'premium' : ''}" viewBox="${vb}" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${inner}</svg>`;
    cache[key] = svg; return svg;
  }
